import{_ as t,o as r,c as a,a4 as o}from"./chunks/framework.DA9C4Pbl.js";const g=JSON.parse('{"title":"arcsecond proxy","description":"","frontmatter":{"title":"arcsecond proxy","visibility":"public","audience":"operator","tier":"reference","source":"generated","cli":"4.2.1"},"headers":[],"relativePath":"reference/commands/proxy.md","filePath":"reference/commands/proxy.md"}'),s={name:"reference/commands/proxy.md"};function n(i,e,d,c,p,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="arcsecond-proxy" tabindex="-1"><code>arcsecond proxy</code> <a class="header-anchor" href="#arcsecond-proxy" aria-label="Permalink to “arcsecond proxy”">​</a></h1><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond proxy [OPTIONS] COMMAND [ARGS]...</span></span></code></pre></div><p>Start and inspect the proxy that serves your cameras.</p><p><strong>Subcommands</strong></p><ul><li><a href="#arcsecond-proxy-start"><code>arcsecond proxy start</code></a> — Serve every registered camera — webcams, network cameras and all-sky cameras alike — over one proxy.</li><li><a href="#arcsecond-proxy-status"><code>arcsecond proxy status</code></a> — Say whether the proxy is running, and what it is serving.</li><li><a href="#arcsecond-proxy-stop"><code>arcsecond proxy stop</code></a> — Stop the running proxy.</li></ul><h2 id="arcsecond-proxy-start" tabindex="-1"><code>arcsecond proxy start</code> <a class="header-anchor" href="#arcsecond-proxy-start" aria-label="Permalink to “arcsecond proxy start”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond proxy start [OPTIONS]</span></span></code></pre></div><p>Serve every registered camera — webcams, network cameras and all-sky cameras alike — over one proxy.</p><p>Starts in the background and gives you your prompt back; stop it with <code>arcsecond proxy stop</code> from anywhere. Use --foreground to run it in this terminal and watch it instead.</p><p>Registers nothing: run <code>arcsecond webcam add</code> or <code>arcsecond allsky add</code> first. Cameras added while it runs are picked up without a restart.</p><p>Set LIVE_IMAGE_PROXY_URL=<a href="http://host.docker.internal" target="_blank" rel="noreferrer">http://host.docker.internal</a>:&lt;PORT&gt; in your .env so Arcsecond.local can reach the proxy.</p><p><strong>Options</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--port INTEGER</code></td><td>TCP port to listen on. [default: 8765]</td></tr><tr><td><code>--host TEXT</code></td><td>Interface to bind. [default: 0.0.0.0]</td></tr><tr><td>`--log-level [debug</td><td>info</td></tr><tr><td><code>--foreground</code></td><td>Run in this terminal and keep it, printing as it goes, instead of starting in the background. Ctrl-C stops it.</td></tr><tr><td><code>--no-autostart</code></td><td>Do not register the proxy to start again when you log in. By default a background proxy comes back after a reboot until <code>arcsecond proxy stop</code> is run.</td></tr></tbody></table><h2 id="arcsecond-proxy-status" tabindex="-1"><code>arcsecond proxy status</code> <a class="header-anchor" href="#arcsecond-proxy-status" aria-label="Permalink to “arcsecond proxy status”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond proxy status [OPTIONS]</span></span></code></pre></div><p>Say whether the proxy is running, and what it is serving.</p><h2 id="arcsecond-proxy-stop" tabindex="-1"><code>arcsecond proxy stop</code> <a class="header-anchor" href="#arcsecond-proxy-stop" aria-label="Permalink to “arcsecond proxy stop”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond proxy stop [OPTIONS]</span></span></code></pre></div><p>Stop the running proxy.</p><p>The mirror of <code>start</code>, and it works from any terminal — the proxy records where it is when it starts, so there is nothing to remember and no port to type. Registered cameras are untouched: this stops serving them, <code>forget</code> is what drops one.</p><p><strong>Options</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--timeout FLOAT</code></td><td>Seconds to wait for it to shut down before insisting. [default: 10.0]</td></tr></tbody></table>',22)])])}const y=t(s,[["render",n]]);export{g as __pageData,y as default};
